#include <bits/stdc++.h>
using namespace std;

using LL = long long;

const LL MOD = 1000000007LL;

LL inv(LL x) {
    LL y = MOD - 2;
    LL res = 1;

    while (y) {
        if (y & 1) res = res * x % MOD;
        x = x * x % MOD;
        y >>= 1;
    }

    return res;
}

LL C(int n, int m) {
    LL ans = 1;
    for (LL i = 1; i <= m; ++i) {
        ans = ans * (n - i + 1) % MOD;
        ans = ans * inv(i) % MOD;
    }
    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    LL ans = 1;
    LL removedInLastRound = 0;
    LL powerOf2 = 1;

    for (int i = 1; i <= 2 * n; ++i) {
        powerOf2 = powerOf2 * 2 % MOD;
        LL currentRound = powerOf2;
        LL removedInCurrentRound = 0;

        if (i > n) {
            removedInCurrentRound = 2 * C(i - 1, n) % MOD;
            removedInCurrentRound =
                (removedInCurrentRound + removedInLastRound * 2) % MOD;
        }

        currentRound =
            (currentRound - removedInCurrentRound + MOD) % MOD;
        ans = (ans + currentRound) % MOD;
        removedInLastRound = removedInCurrentRound;
    }

    cout << ans;
    return 0;
}

